"""Year-round private journal intake; independent of the anthology."""
import re

def render_monthly_submission(root):
    path=root/'submit.html'
    text=path.read_text()
    body='''<main id="main" class="wrap monthly-form" tabindex="-1"><header class="monthly-opening"><span class="eyebrow">Odia · Hindi · English</span><h1>Send a poem</h1><p>Open throughout the year. Editors choose the edition month.</p></header>
<p class="small">Read our <a href="about.html#editorial-policies">editorial policies</a>. Your entry stays private until approved for publication. Submissions are retained indefinitely. Keep your own copy.</p>
<p id="monthly-status" role="status" tabindex="-1">Checking online submissions…</p>
<noscript><p>Online submission needs JavaScript. Email your poem, title, name and short biography to <a href="mailto:kabitaliveweb@gmail.com">kabitaliveweb@gmail.com</a>.</p></noscript>
<form id="monthly-form" action="submit.html" method="post" aria-labelledby="monthly-form-heading" hidden>
<h2 id="monthly-form-heading" class="sr-only">Poetry submission</h2><p class="small">Fields marked optional can be left blank. Unfinished text is saved in this tab; permissions and image files are not.</p>
<fieldset id="monthly-fields"><legend>Your poem</legend>
<label for="monthly-title">Poem title</label><input id="monthly-title" name="title" maxlength="200" required>
<fieldset class="monthly-options"><legend>Language</legend><label><input type="radio" name="language" value="or" required> Odia</label><label><input type="radio" name="language" value="hi"> Hindi</label><label><input type="radio" name="language" value="en"> English</label></fieldset>
<label for="monthly-poem">Your poem</label><p id="monthly-poem-help" class="small">Line and stanza breaks are preserved. Fonts, bold and italics are not retained; describe special formatting in Notes. Up to 30,000 characters.</p><textarea id="monthly-poem" name="poem" rows="12" maxlength="30000" aria-describedby="monthly-poem-help" required dir="auto"></textarea>
<fieldset id="monthly-ai-declaration"><legend>Authorship and assistance</legend><fieldset class="monthly-options"><legend>About the work</legend><label><input type="radio" name="kind" value="original" required> Original poem</label><label><input type="radio" name="kind" value="translation"> Translation</label></fieldset>
<div id="monthly-translation" hidden><label for="monthly-credits">Original poet and translator</label><textarea id="monthly-credits" name="credits" rows="2" maxlength="1000" disabled></textarea><label for="monthly-translation-ai">AI assistance with this translation</label><select id="monthly-translation-ai" name="translationAi" disabled><option value="">Choose</option><option value="none">None</option><option value="assisted">AI assisted</option></select><label for="monthly-translation-ai-note">Describe translation assistance (required if used)</label><textarea id="monthly-translation-ai-note" name="translationAiExplanation" maxlength="2000" rows="2" disabled></textarea></div>
<label for="monthly-previous">Previous publication or simultaneous submissions (optional)</label><textarea id="monthly-previous" name="previous" rows="2" maxlength="2000"></textarea>
<fieldset class="monthly-options monthly-stack"><legend>Assistance with the original poem</legend><p class="small">Select all that apply. <a href="about.html#policy-ai-assistance">Read the authorship policy</a>.</p><label><input type="checkbox" name="aiUses" value="none"> None</label><label><input type="checkbox" name="aiUses" value="proofreading"> Spelling, grammar or accessibility assistance</label><label><input type="checkbox" name="aiUses" value="critique"> AI research, brainstorming or critique</label><label><input type="checkbox" name="aiUses" value="rewriting"> Substantial AI editing or rewriting</label><label><input type="checkbox" name="aiUses" value="generation"> AI-generated lines, stanzas or poem</label></fieldset>
<div id="monthly-ai-note-wrap" hidden><label for="monthly-ai-note">Briefly describe the assistance</label><textarea id="monthly-ai-note" name="aiExplanation" rows="2" maxlength="2000" disabled></textarea></div>
</fieldset><label for="monthly-notes">Notes for the editors (optional)</label><textarea id="monthly-notes" name="notes" rows="2" maxlength="2000"></textarea>
<details><summary>Accompanying artwork (optional)</summary><p class="small">JPEG, PNG or WebP, up to 5 MB. You must have permission to share it. Artwork is reviewed before use.</p><label for="monthly-artwork">Choose artwork</label><input id="monthly-artwork" name="artworkFile" type="file" accept="image/jpeg,image/png,image/webp"><label for="monthly-artwork-credit">Artist / credit (required with artwork)</label><input id="monthly-artwork-credit" name="artworkCredit" maxlength="200"><label class="monthly-consent"><input type="checkbox" name="artworkPermission"> I permit publication of this artwork with its credit.</label></details>
</fieldset>
<fieldset><legend>About you</legend>
<label for="monthly-name">Name to publish</label><input id="monthly-name" name="name" autocomplete="name" maxlength="120" required>
<label for="monthly-email">Email address (private)</label><input id="monthly-email" name="email" type="email" autocomplete="email" autocapitalize="none" autocorrect="off" spellcheck="false" maxlength="254" required>
<label class="monthly-consent"><input type="checkbox" name="returningAuthor"> I have been published in Kabita Live before.</label>
<div id="monthly-returning" hidden><label for="monthly-author">Your author profile</label><select id="monthly-author" name="authorId" disabled><option value="">Choose your profile, or leave blank if not listed</option></select><div id="monthly-author-preview"></div><label class="monthly-consent"><input type="checkbox" name="requestProfileUpdate"> Propose a profile update</label><p class="small">Editors confirm the match. Existing details and portrait stay unchanged unless an update is reviewed.</p></div>
<div id="monthly-profile-fields"><label for="monthly-bio">Short biography</label><textarea id="monthly-bio" name="bio" rows="4" maxlength="5000" required dir="auto"></textarea>
<label for="monthly-social">Public website or social links (optional)</label><p class="small" id="monthly-social-help">Up to four HTTPS links, one per line. Approved links may appear on your author page.</p><textarea id="monthly-social" name="socialLinks" rows="2" maxlength="2004" aria-describedby="monthly-social-help" autocapitalize="none" autocorrect="off" spellcheck="false"></textarea>
<details><summary>Author photograph (optional)</summary><p class="small">JPEG, PNG or WebP, up to 5 MB.</p><label for="monthly-photo">Choose photograph</label><input id="monthly-photo" name="photoFile" type="file" accept="image/jpeg,image/png,image/webp"><label class="monthly-consent"><input type="checkbox" name="photoPublishPermission"> I permit publication of this photograph on my author profile.</label><label class="monthly-consent"><input type="checkbox" name="portraitTreatmentPermission"> I also permit an artistic portrait based on this photograph.</label></details></div>
</fieldset>
<fieldset><legend>Permissions</legend><label class="monthly-consent"><input type="checkbox" name="translationPermission"> I permit Kabita Live to prepare translations of this poem for my review.</label><fieldset id="monthly-targets" class="monthly-options" hidden><legend>Permitted languages</legend><label><input type="checkbox" name="translationLanguages" value="or"> Odia</label><label><input type="checkbox" name="translationLanguages" value="hi"> Hindi</label><label><input type="checkbox" name="translationLanguages" value="en"> English</label></fieldset><p class="small">Optional. Permission does not affect selection of your original or authorise automatic publication of a translation. Only grant rights you hold.</p>
<label class="monthly-consent"><input type="checkbox" name="consent" required> I have the right to submit this work, have disclosed assistance and previous publication, and agree to the editorial policies, nonexclusive permission for agreed Kabita Live publication and its online archive, and indefinite private storage for review. I retain ownership; translation and image permissions are separate.</label></fieldset>
<div class="monthly-actions"><button type="submit" class="btn solid" id="monthly-review-button">Review your entry</button><button type="button" class="btn" id="monthly-clear">Clear saved draft</button></div></form>
<section id="monthly-summary" hidden aria-labelledby="monthly-summary-title"><h2 id="monthly-summary-title" tabindex="-1">Review and submit</h2><div id="monthly-summary-content"></div><p class="small">Receipt is not a promise of selection. Your text and declarations will be retained with this entry.</p><div id="monthly-recovery-files" hidden><p>For an unfinished upload, choose the same image again. Already uploaded files are reused.</p><label for="monthly-recovery-photo">Same photograph (if not uploaded)</label><input id="monthly-recovery-photo" type="file" accept="image/jpeg,image/png,image/webp"><label for="monthly-recovery-artwork">Same artwork (if not uploaded)</label><input id="monthly-recovery-artwork" type="file" accept="image/jpeg,image/png,image/webp"></div><label id="monthly-reconsent-label" hidden class="monthly-consent"><input type="checkbox" id="monthly-reconsent"> I confirm the rights, declarations and permissions displayed above and agree to indefinite private storage of this entry.</label><div class="monthly-actions"><button class="btn" id="monthly-edit" type="button">Edit entry</button><button class="btn solid" id="monthly-send" type="button">Submit poem</button></div></section>
<section id="monthly-result" hidden><h2 tabindex="-1" id="monthly-result-title">Poem received</h2><p id="monthly-result-poem"></p><p id="monthly-reference"></p><p>Your poem is with the editors. Keep this reference as confirmation. If an email acknowledgement does not arrive, you do not need to submit again. This confirms receipt, not selection.</p><p class="small">Keep your reference and your own copy. Questions? <a href="mailto:kabitaliveweb@gmail.com">kabitaliveweb@gmail.com</a>.</p></section>
<p class="small">Prefer email? <a href="mailto:kabitaliveweb@gmail.com">kabitaliveweb@gmail.com</a></p></main>'''
    text=re.sub(r'<main\b.*?</main>',lambda _:body,text,count=1,flags=re.S)
    text=text.replace('</head>','<link rel="stylesheet" href="assets/monthly-submissions.css?v=2"><script type="module" src="assets/monthly-form.mjs?v=2"></script></head>',1)
    text=text.replace('<script defer src="assets/analytics.js"></script>','')
    path.write_text(text)
